/* app.client.3.js — Client Portal: finance */
'use strict';
const visitPicker = (id, onPick, placeholder) => `<div class="scan"><input class="inp" id="${id}" placeholder="${placeholder || t('visitSearchPlaceholder')}" onkeydown="if(event.key==='Enter')${onPick}(this.value)"><button class="btn primary" onclick="${onPick}(el('#${id}').value)">${ic('search')} ${t('search')}</button></div>`;
function findVisits(q) { q = (q || '').trim().toLowerCase(); if (!q) return []; return DB.visits.filter(v => { const p = patientOf(v); return v.acc.includes(q) || p.no.toLowerCase().includes(q) || p.name.toLowerCase().includes(q) || (p.nameAr || '').includes(q) || p.mobile.includes(q); }); }
const myTreasury = () => byId(DB.treasuries, App.user.treasury);

/* ---------- payments ---------- */
App.screens.payments = () => { const q = App.store.payq || ''; const rows = q ? findVisits(q) : DB.visits.filter(v => visitTotals(v).remaining !== 0 || isToday(v.date)); return pageHead(t('payments'), `${t('finance')} / ${t('payments')}`) + `<div class="info">${t('paymentsNote')} · ${t('treasury')}: <b>${esc(L(myTreasury()))}</b> · ${t('device')}: <span class="mono">${App.user.device}</span></div>` + card({ flush: true, body: `<div class="toolbar"><div class="search-wrap">${ic('search')}<input class="inp" placeholder="${t('visitSearchPlaceholder')}" value="${esc(q)}" oninput="App.store.payq=this.value;renderMain()"></div></div>` + grid({ cols: [{ k: 'acc', l: 'accession', f: r => `<b>${r.acc}</b>` }, { k: 'patient', l: 'patient', f: r => esc(L(patientOf(r))) }, { k: 'payer', l: 'payer', f: r => esc(L(payerById(r.payer))) }, { k: 'total', l: 'total', f: r => money(visitTotals(r).total) }, { k: 'disc', l: 'discount', f: r => money(visitTotals(r).discount) }, { k: 'pt', l: 'patientShare', f: r => money(visitTotals(r).patientShare) }, { k: 'paid', l: 'totalPaid', f: r => money(visitTotals(r).paid) }, { k: 'ref', l: 'refunded', f: r => money(visitTotals(r).refunded) }, { k: 'rem', l: 'remaining', f: r => { const x = visitTotals(r).remaining; return x > 0 ? badge(money(x), 'warn') : x < 0 ? badge(money(x), 'bad') : badge(t('settled'), 'ok'); } }], rows, actions: r => `<button class="btn sm primary" onclick="payModal(${r.id})">${ic('dollar', 12)} ${t('pay')}</button>` + (visitTotals(r).remaining < 0 ? ` <button class="btn sm danger" onclick="refundModal(${r.id})">${ic('undo', 12)} ${t('refund')}</button>` : '') + rowBtn('file', 'receipts', `receiptsModal(${r.id})`) }) }); };
function payModal(id) { const v = byId(DB.visits, id); const tot = visitTotals(v); modal({ title: `${t('collectPayment')} · ${v.acc}`, size: 'sm', body: `<div class="kv mb"><dt>${t('patient')}</dt><dd>${esc(L(patientOf(v)))}</dd><dt>${t('patientShare')}</dt><dd>${money(tot.patientShare)}</dd><dt>${t('totalPaid')}</dt><dd>${money(tot.paid)}</dd><dt>${t('remaining')}</dt><dd><b>${money(tot.remaining)}</b></dd></div>${tot.remaining <= 0 ? `<div class="ok-strip">${t('nothingDue')}</div>` : formGrid([{ k: 'amount', l: 'amount', type: 'number', req: true, val: tot.remaining, help: 'partialHelp' }, { k: 'method', l: 'paymentMethod', type: 'select', req: true, opts: [['Cash', () => t('cash')], ['Card', () => t('card')], ['POS', () => t('pos')], ['Transfer', () => t('bankTransfer')]], val: 'Cash' }, { k: 'ref', l: 'transactionRef', help: 'refHelp' }, { k: 'treasury', l: 'treasury', type: 'static', html: esc(L(myTreasury())) + ' · ' + App.user.device }], {})}`, foot: `<button class="btn" onclick="closeModal()">${t('cancel')}</button>${tot.remaining > 0 ? `<button class="btn primary" onclick="paySave(${id})">${ic('save')} ${t('addPayment')}</button>` : ''}` }); }
function paySave(id) { if (!validateForm()) return; const o = readForm(); const v = byId(DB.visits, id); const tot = visitTotals(v); if (o.amount <= 0 || o.amount > tot.remaining + 0.001) return toast(t('amountInvalid'), 'error', money(tot.remaining)); if (o.method !== 'Cash' && !o.ref) return toast(t('refRequired'), 'error'); const pay = { id: Date.now(), date: nowISO(), amount: Number(o.amount), method: o.method, ref: o.ref, user: userName(), treasury: App.user.treasury, device: App.user.device }; v.payments.push(pay); audit('Payment', v.acc, `${money(pay.amount)} ${pay.method}`); closeModal(); renderMain(); toast(t('paymentSaved'), 'ok', money(pay.amount)); if (DB.parameters.autoPrintReceipt) docReceipt(id, pay.id); }
function receiptsModal(id) { const v = byId(DB.visits, id); modal({ title: `${t('receipts')} · ${v.acc}`, size: 'sm', body: grid({ cols: [{ k: 'date', l: 'date', f: r => fmtDT(r.date) }, { k: 'amount', l: 'amount', f: r => money(r.amount) }, { k: 'method', l: 'paymentMethod', f: r => `${r.method}${r.ref ? ' · ' + r.ref : ''}` }, { k: 'user', l: 'cashier' }], rows: v.payments, nofoot: true, actions: r => rowBtn('printer', 'reprint', `docReceipt(${id},${r.id})`) }) + (v.refunds.length ? `<div class="section-title">${t('refunds')}</div>` + grid({ cols: [{ k: 'date', l: 'date', f: r => fmtDT(r.date) }, { k: 'amount', l: 'amount', f: r => money(r.amount) }, { k: 'reason', l: 'reason' }, { k: 'user', l: 'cashier' }], rows: v.refunds, nofoot: true }) : ''), foot: `<button class="btn" onclick="closeModal()">${t('close')}</button><button class="btn" onclick="toast(t('sentToPrinter'),'ok')">${ic('printer')} ${t('printInvoice')}</button>` }); }

/* ---------- refunds ---------- */
App.screens.refunds = () => { const rows = DB.visits.filter(v => visitTotals(v).remaining < 0 || v.refunds.length); return pageHead(t('refunds'), `${t('finance')} / ${t('refunds')}`) + `<div class="info">${t('refundNote')}</div>` + card({ body: visitPicker('rfq', 'refundLookup') }) + card({ title: t('negativeBalances'), flush: true, body: grid({ cols: [{ k: 'acc', l: 'accession', f: r => `<b>${r.acc}</b>` }, { k: 'patient', l: 'patient', f: r => esc(L(patientOf(r))) }, { k: 'paid', l: 'totalPaid', f: r => money(visitTotals(r).paid) }, { k: 'due', l: 'patientShare', f: r => money(visitTotals(r).patientShare) }, { k: 'rem', l: 'balance', f: r => { const x = visitTotals(r).remaining; return x < 0 ? badge(money(x), 'bad') : badge(money(x), 'ok'); } }, { k: 'refunds', l: 'refunded', f: r => money(visitTotals(r).refunded) }], rows, actions: r => visitTotals(r).remaining < 0 ? `<button class="btn sm danger" onclick="refundModal(${r.id})">${ic('undo', 12)} ${t('refund')}</button>` : '' }) }); };
function refundLookup(q) { const v = findVisits(q)[0]; if (!v) return toast(t('visitNotFound'), 'error'); refundModal(v.id); }
function refundModal(id) { const v = byId(DB.visits, id); const tot = visitTotals(v); const refundable = Math.max(0, -tot.remaining); modal({ title: `${t('refund')} · ${v.acc}`, size: 'sm', body: `<div class="${refundable ? 'warn-strip' : 'info'}">${t('refundableAmount')}: <b>${money(refundable)}</b> · ${t('refundRule')}</div>` + formGrid([{ k: 'amount', l: 'refundAmount', type: 'number', req: true, val: refundable }, { k: 'method', l: 'paymentMethod', type: 'select', req: true, opts: [['Cash', () => t('cash')], ['Card', () => t('card')]], val: 'Cash' }, { k: 'reason', l: 'refundReason', type: 'select', req: true, opts: reasonOpts('Refund'), span: 2 }], {}), foot: `<button class="btn" onclick="closeModal()">${t('cancel')}</button><button class="btn danger" ${refundable ? '' : 'disabled'} onclick="refundSave(${id})">${ic('undo')} ${t('refund')}</button>` }); }
function refundSave(id) { if (!validateForm()) return; const o = readForm(); const v = byId(DB.visits, id); const refundable = Math.max(0, -visitTotals(v).remaining); if (o.amount <= 0 || o.amount > refundable + 0.001) return toast(t('amountInvalid'), 'error', money(refundable)); const rf = { id: Date.now(), date: nowISO(), amount: Number(o.amount), method: o.method, reason: o.reason, user: userName(), treasury: App.user.treasury, device: App.user.device }; v.refunds.push(rf); audit('Refund', v.acc, `${money(rf.amount)} · ${rf.reason}`); closeModal(); renderMain(); toast(t('refundSaved'), 'ok', t('refundReceiptSign')); modal({ title: t('refundReceipt'), size: 'lg', body: `<div class="paper">${paperHead(t('refundReceipt'))}<div class="kv"><dt>${t('patient')}</dt><dd>${esc(L(patientOf(v)))}</dd><dt>${t('accession')}</dt><dd>${v.acc}</dd><dt>${t('amount')}</dt><dd><b>${money(rf.amount)}</b> (${rf.method})</dd><dt>${t('reason')}</dt><dd>${esc(rf.reason)}</dd><dt>${t('cashier')}</dt><dd>${esc(rf.user)} · ${esc(L(myTreasury()))}</dd></div><div class="sig"><div>${t('patientSignature')}</div><div>${t('cashier')}</div></div></div>`, foot: `<button class="btn" onclick="closeModal()">${t('close')}</button><button class="btn primary" onclick="toast(t('sentToPrinter'),'ok')">${ic('printer')} ${t('print')}</button>` }); }

/* ---------- money transfer ---------- */
const MT = { visitId: null, payer: null, tier: null };
App.screens.moneyTransfer = () => { const v = MT.visitId ? byId(DB.visits, MT.visitId) : null; return pageHead(t('moneyTransfer'), `${t('finance')} / ${t('moneyTransfer')}`) + `<div class="info">${t('transferNote')}</div>` + card({ body: visitPicker('mtq', 'mtLookup') }) + (v ? (() => { const tot = visitTotals(v); const np = MT.payer || v.payer, nt = MT.tier || v.tier; const preview = v.lines.filter(l => l.status !== 'Cancelled').map(l => ({ l, p: priceFor(l.service, np, nt) })); const newPt = preview.reduce((s, x) => s + x.p.patient, 0), newPy = preview.reduce((s, x) => s + x.p.payer, 0);
  return `<div class="card"><div class="card-head"><div class="card-title">${v.acc} · ${esc(L(patientOf(v)))}</div><div class="card-sub">${t('currentContract')}: <b>${esc(L(payerById(v.payer)))} / ${esc(L(tierOf(v.payer, v.tier)))}</b> · ${t('patientShare')} ${money(tot.patientShare)} · ${t('totalPaid')} ${money(tot.paid)}</div></div><div class="card-body">${tabs('mtTabs', [['rank', 'contractTransfer'], ['normal', 'lineTransfer']], 'rank')}${pane('mtTabs', 'rank', `<div class="form-grid">${field({ k: 'np', l: 'newPayer', type: 'select', opts: payerOpts(), val: np, onchange: 'MT.payer=Number(this.value);MT.tier=payerById(MT.payer).tiers[0].id;renderMain()' })}${field({ k: 'nt', l: 'newTier', type: 'select', opts: payerById(np).tiers.map(x => [x.id, () => L(x)]), val: nt, onchange: 'MT.tier=Number(this.value);renderMain()' })}</div><div class="table-wrap mt"><table class="g compact"><thead><tr><th>${t('service')}</th><th class="right">${t('currentPatient')}</th><th class="right">${t('currentPayer')}</th><th class="right">${t('newPatient')}</th><th class="right">${t('newPayer')}</th></tr></thead><tbody>${preview.map(x => `<tr><td>${esc(L(svcById(x.l.service)))}</td><td class="right">${num(x.l.patient)}</td><td class="right">${num(x.l.payer)}</td><td class="right"><b>${num(x.p.patient)}</b></td><td class="right"><b>${num(x.p.payer)}</b></td></tr>`).join('')}</tbody></table></div><div class="row mt" style="justify-content:space-between"><div>${t('newPatientShare')}: <b>${money(newPt - tot.discount)}</b> · ${t('newPayerShare')}: <b>${money(newPy)}</b> · ${t('resultingBalance')}: <b class="${newPt - tot.discount - tot.paid + tot.refunded < 0 ? 'muted' : ''}">${money(newPt - tot.discount - tot.paid + tot.refunded)}</b></div><button class="btn primary" onclick="mtApply(${v.id})" ${np === v.payer && nt === v.tier ? 'disabled' : ''}>${ic('repeat')} ${t('applyTransfer')}</button></div>`, true)}${pane('mtTabs', 'normal', `<div class="help mb">${t('lineTransferHelp')}</div><div class="table-wrap"><table class="g compact"><thead><tr><th>${t('service')}</th><th>${t('listPatient')}</th><th>${t('listPayer')}</th><th>${t('actualPatient')}</th><th>${t('actualPayer')}</th></tr></thead><tbody>${v.lines.filter(l => l.status !== 'Cancelled').map(l => { const p = priceFor(l.service, v.payer, v.tier); return `<tr><td>${esc(L(svcById(l.service)))}</td><td>${num(p.patient)}</td><td>${num(p.payer)}</td><td><input class="inp sm" type="number" value="${l.patient}" onchange="mtLine(${v.id},${l.id},'patient',this.value)"></td><td><input class="inp sm" type="number" value="${l.payer}" onchange="mtLine(${v.id},${l.id},'payer',this.value)"></td></tr>`; }).join('')}</tbody></table></div>`)}</div></div>`; })() : ''); };
function mtLookup(q) { const v = findVisits(q)[0]; if (!v) return toast(t('visitNotFound'), 'error'); MT.visitId = v.id; MT.payer = v.payer; MT.tier = v.tier; renderMain(); }
function mtApply(id) { const v = byId(DB.visits, id); const old = `${L(payerById(v.payer))}/${L(tierOf(v.payer, v.tier))}`; v.payer = MT.payer; v.tier = MT.tier; v.lines.forEach(l => { const p = priceFor(l.service, v.payer, v.tier); l.patient = p.patient; l.payer = p.payer; }); v.transfers.push({ time: nowISO(), user: userName(), from: old, to: `${L(payerById(v.payer))}/${L(tierOf(v.payer, v.tier))}` }); audit('Contract transfer', v.acc, `${old} → ${L(payerById(v.payer))}`); renderMain(); const rem = visitTotals(v).remaining; toast(t('transferApplied'), 'ok', rem < 0 ? `${t('refundDue')} ${money(-rem)}` : rem > 0 ? `${t('remaining')} ${money(rem)}` : ''); }
function mtLine(vid, lid, k, val) { const v = byId(DB.visits, vid); const l = v.lines.find(x => x.id === lid); l[k] = Number(val); audit('Line value transfer', v.acc, `${svcById(l.service).short} ${k} = ${val}`); toast(t('saved'), 'ok'); }

/* ---------- cancellations ---------- */
App.screens.cancellations = () => { const rows = DB.visits.filter(v => v.lines.some(l => l.status === 'Cancelled')); return pageHead(t('cancellations'), `${t('finance')} / ${t('cancellations')}`) + `<div class="info">${t('cancelNote')}</div>` + card({ body: visitPicker('cnq', 'cancelLookup') }) + card({ title: t('cancelledServices'), flush: true, body: grid({ cols: [{ k: 'acc', l: 'accession', f: r => `<b>${r.acc}</b>` }, { k: 'patient', l: 'patient', f: r => esc(L(patientOf(r))) }, { k: 'lines', l: 'cancelledServices', f: r => r.lines.filter(l => l.status === 'Cancelled').map(l => `<span class="tag">${svcById(l.service).short} · ${esc(l.cancelReason || '')}</span>`).join('') }, { k: 'by', l: 'user', f: r => esc(r.lines.find(l => l.status === 'Cancelled')?.cancelUser || '') }, { k: 'bal', l: 'balance', f: r => money(visitTotals(r).remaining) }], rows, nofoot: true }) }); };
function cancelLookup(q) { const v = findVisits(q)[0]; if (!v) return toast(t('visitNotFound'), 'error'); modal({ title: `${t('cancelServices')} · ${v.acc}`, size: 'lg', body: `<div class="warn-strip">${t('cancelWarn')}</div><table class="g compact"><thead><tr><th></th><th>${t('service')}</th><th>${t('status')}</th><th>${t('testStatus')}</th><th class="right">${t('patientShare')}</th><th class="right">${t('payerShare')}</th></tr></thead><tbody>${v.lines.map(l => { const rs = DB.results.filter(r => r.visit === v.id && (r.service === l.service || svcById(l.service).type === 'Package')); const verified = rs.some(r => stIdx(r.status) >= 3); return `<tr><td><input type="checkbox" class="cl" value="${l.id}" ${l.status === 'Cancelled' || verified ? 'disabled' : ''}></td><td>${esc(L(svcById(l.service)))}</td><td>${sb(l.status)}</td><td>${rs.length ? sb(SCREEN_ORDER[Math.min(...rs.map(r => stIdx(r.status)))]) : '—'}${verified ? ` <span class="small muted">${t('cannotCancelVerified')}</span>` : ''}</td><td class="right">${num(l.patient)}</td><td class="right">${num(l.payer)}</td></tr>`; }).join('')}</tbody></table><div class="field mt"><label>${t('cancellationReason')} <span class="req">*</span></label><select class="inp" id="cnReason"><option value="">${t('select')}</option>${reasonOpts('Cancellation').map(([v2, l]) => `<option value="${v2}">${esc(l())}</option>`).join('')}</select></div>`, foot: `<button class="btn" onclick="closeModal()">${t('cancel')}</button><button class="btn danger" onclick="cancelApply(${v.id})">${ic('slash')} ${t('cancelSelected')}</button>` }); }
function cancelApply(id) { const v = byId(DB.visits, id); const ids = els('.cl:checked').map(i => Number(i.value)); const reason = el('#cnReason').value; if (!ids.length) return toast(t('selectServices'), 'error'); if (!reason) return toast(t('selectReason'), 'error'); ids.forEach(lid => { const l = v.lines.find(x => x.id === lid); l.status = 'Cancelled'; l.cancelReason = reason; l.cancelUser = userName(); l.cancelTime = nowISO(); const s = svcById(l.service); const svcIds = s.type === 'Package' ? s.members.map(m => m.service) : [s.id]; v.samples.forEach(smp => { smp.services = smp.services.filter(x => !svcIds.includes(x)); if (!smp.services.length && smp.status !== 'Rejected') { smp.status = 'Cancelled'; smp.events.push({ status: 'Cancelled', time: nowISO(), user: userName(), location: reason }); } }); DB.results = DB.results.filter(r => !(r.visit === v.id && svcIds.includes(r.service))); }); audit('Services cancelled', v.acc, `${ids.length} · ${reason}`); closeModal(); renderMain(); const rem = visitTotals(v).remaining; toast(t('cancelled'), 'warn', rem < 0 ? `${t('refundDue')} ${money(-rem)}` : ''); }

/* ---------- batch payment ---------- */
App.screens.batchPayment = p => { const no = p.batch || App.store.bpNo || ''; App.store.bpNo = no; const b = DB.batches.find(x => String(x.no) === String(no)); const vs = b ? b.visits.map(id => byId(DB.visits, id)).filter(Boolean) : []; const totalRem = vs.reduce((s, v) => s + Math.max(0, visitTotals(v).remaining), 0); return pageHead(t('batchPayment'), `${t('finance')} / ${t('batchPayment')}`) + card({ body: `<div class="scan"><input class="inp" id="bpq" value="${esc(no)}" placeholder="${t('batchNo')}" onkeydown="if(event.key==='Enter')navigate('batchPayment',{batch:this.value})"><button class="btn primary" onclick="navigate('batchPayment',{batch:el('#bpq').value})">${ic('search')} ${t('search')}</button></div><div class="row mt">${DB.batches.map(x => `<span class="chip" style="cursor:pointer" onclick="navigate('batchPayment',{batch:${x.no}})">${t('batchNo')} ${x.no} · ${x.type} · ${esc(x.company || byId(DB.sendingLabs, x.lab)?.name || '')}</span>`).join('')}</div>` }) + (b ? card({ title: `${t('batchNo')} ${b.no} · ${b.type} · ${esc(L(payerById(b.payer)))} / ${esc(L(tierOf(b.payer, b.tier)))}`, actions: totalRem > 0 ? `<button class="btn primary" onclick="batchPayAll(${b.no})">${ic('dollar', 14)} ${t('payAll')} ${money(totalRem)}</button>` : badge(t('settled'), 'ok'), flush: true, body: grid({ cols: [{ k: 'acc', l: 'accession', f: r => `<b>${r.acc}</b>` }, { k: 'patient', l: 'patient', f: r => esc(L(patientOf(r))) }, { k: 'pt', l: 'patientShare', f: r => money(visitTotals(r).patientShare) }, { k: 'py', l: 'payerShare', f: r => money(visitTotals(r).payerShare) }, { k: 'paid', l: 'totalPaid', f: r => money(visitTotals(r).paid) }, { k: 'rem', l: 'remaining', f: r => money(visitTotals(r).remaining) }], rows: vs, nofoot: true, actions: r => visitTotals(r).remaining > 0 ? `<button class="btn sm" onclick="payModal(${r.id})">${t('pay')}</button>` : '' }) + (b.type === 'Lab-to-Lab' ? `<div class="info" style="margin:12px">${t('l2lBilledToLab')}</div>` : '') }) : (no ? `<div class="bad-strip">${t('batchNotFound')}</div>` : '')); };
function batchPayAll(no) { const b = DB.batches.find(x => x.no === no); let n = 0, sum = 0; b.visits.map(id => byId(DB.visits, id)).forEach(v => { const rem = visitTotals(v).remaining; if (rem > 0) { v.payments.push({ id: Date.now() + n, date: nowISO(), amount: rem, method: 'Cash', ref: 'Batch ' + no, user: userName(), treasury: App.user.treasury, device: App.user.device }); n++; sum += rem; } }); audit('Batch payment', 'Batch ' + no, money(sum)); renderMain(); toast(t('paymentSaved'), 'ok', `${n} ${t('visits')} · ${money(sum)}`); }

/* ---------- treasuries & requests ---------- */
App.screens.treasuries = { key: 'treasuries', group: 'finance', title: 'treasuries', singular: 'treasury', data: 'treasuries', cols: [{ k: 'code', l: 'code', w: '80px' }, { k: 'name', l: 'name' }, { k: 'branch', l: 'branch', f: r => esc(L(byId(DB.branches, r.branch))) }, { k: 'users', l: 'approvedUsers', f: r => DB.treasuryRequests.filter(x => x.treasury === r.id && x.status === 'Approved').map(x => `<span class="tag">${esc(L(x, 'user'))}</span>`).join('') || '—' }, { k: 'status', l: 'status', f: r => sb(r.status) }], fields: [{ k: 'code', l: 'code', req: true }, { k: 'branch', l: 'branch', type: 'select', req: true, opts: branchOpts }, ...bilingual(), statusField], read: root => { const o = readForm(root); o.branch = Number(o.branch); return o; } };
App.screens.treasuryRequests = () => pageHead(t('treasuryRequests'), `${t('finance')} / ${t('treasuryRequests')}`, `<button class="btn primary" onclick="requestTreasury()">${ic('key')} ${t('requestTreasury')}</button>`) + `<div class="info">${t('treasuryRequestNote')}</div>` + card({ flush: true, body: grid({ cols: [{ k: 'user', l: 'requestedBy', f: r => esc(L(r, 'user')) }, { k: 'branch', l: 'branch', f: r => esc(L(byId(DB.branches, r.branch))) }, { k: 'treasury', l: 'treasury', f: r => esc(L(byId(DB.treasuries, r.treasury))) }, { k: 'device', l: 'deviceId', f: r => `<span class="mono">${r.device}</span>` }, { k: 'requested', l: 'date', f: r => fmtDT(r.requested) }, { k: 'status', l: 'status', f: r => sb(r.status) }], rows: DB.treasuryRequests, nofoot: true, actions: r => r.status === 'Pending' ? `<button class="btn sm ok" onclick="byId(DB.treasuryRequests,${r.id}).status='Approved';audit('Treasury approved','${r.device}','');renderMain();toast(t('approved'),'ok')">${t('approve')}</button> <button class="btn sm danger" onclick="byId(DB.treasuryRequests,${r.id}).status='Rejected';renderMain();toast(t('rejected'),'warn')">${t('reject')}</button>` : r.status === 'Approved' ? `<button class="btn sm" onclick="byId(DB.treasuryRequests,${r.id}).status='Rejected';renderMain();toast(t('revoked'),'warn')">${t('revoke')}</button>` : '' }) });
